import re

_PATTERN = re.compile(
    r"(?i)(?<![A-Z0-9])part\s*[:=]\s*([A-Z]{3})-([0-9]{4})-([A-Z])(?![A-Z0-9])"
)


def scan_part_codes(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    def generate():
        for match in _PATTERN.finditer(text):
            prefix, digits, check = match.groups()
            prefix = prefix.upper()
            check = check.upper()
            total = sum(ord(char) - ord("A") for char in prefix)
            total += sum(int(char) for char in digits)
            check_value = ord(check) - ord("A") + 1
            if total % 26 == check_value % 26:
                yield prefix + digits + check

    return generate()

